#!/usr/bin/env bun
import { readFileSync } from "fs";

interface RawTask {
  id?: unknown;
  duration?: unknown;
  dependsOn?: unknown;
}

interface Task {
  id: string;
  duration: number;
  dependsOn: string[];
}

function fail(msg: string): never {
  process.stderr.write(msg.endsWith("\n") ? msg : msg + "\n");
  process.exit(1);
}

function parseTasks(raw: unknown): Task[] {
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    fail("Invalid input: expected a JSON object with a 'tasks' array.");
  }
  const obj = raw as Record<string, unknown>;
  const tasksRaw = obj.tasks;
  if (!Array.isArray(tasksRaw)) {
    fail("Invalid input: 'tasks' must be an array.");
  }
  const tasks: Task[] = [];
  const ids = new Set<string>();
  for (let i = 0; i < tasksRaw.length; i++) {
    const t = tasksRaw[i];
    if (typeof t !== "object" || t === null || Array.isArray(t)) {
      fail(`Invalid task at index ${i}: expected an object.`);
    }
    const rt = t as RawTask;
    if (typeof rt.id !== "string" || rt.id.length === 0) {
      fail(`Invalid task at index ${i}: 'id' must be a non-empty string.`);
    }
    if (ids.has(rt.id)) {
      fail(`Invalid task at index ${i}: duplicate id '${rt.id}'.`);
    }
    if (
      typeof rt.duration !== "number" ||
      !Number.isFinite(rt.duration) ||
      rt.duration < 0
    ) {
      fail(
        `Invalid task '${rt.id}': 'duration' must be a finite non-negative number.`
      );
    }
    let deps: unknown = rt.dependsOn;
    if (deps === undefined) deps = [];
    if (!Array.isArray(deps)) {
      fail(`Invalid task '${rt.id}': 'dependsOn' must be an array.`);
    }
    const depSet = new Set<string>();
    for (const d of deps as unknown[]) {
      if (typeof d !== "string" || d.length === 0) {
        fail(
          `Invalid task '${rt.id}': each dependency must be a non-empty string.`
        );
      }
      if (d === rt.id) {
        fail(`Invalid task '${rt.id}': a task cannot depend on itself.`);
      }
      if (depSet.has(d)) {
        fail(`Invalid task '${rt.id}': duplicate dependency '${d}'.`);
      }
      depSet.add(d);
    }
    ids.add(rt.id);
    tasks.push({
      id: rt.id,
      duration: rt.duration,
      dependsOn: deps as string[],
    });
  }
  for (const t of tasks) {
    for (const d of t.dependsOn) {
      if (!ids.has(d)) {
        fail(`Invalid task '${t.id}': unknown dependency '${d}'.`);
      }
    }
  }
  return tasks;
}

function cmpSeq(a: string[], b: string[]): number {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    if (a[i] < b[i]) return -1;
    if (a[i] > b[i]) return 1;
  }
  return a.length - b.length;
}

function findCycle(
  idToTask: Map<string, Task>,
  residual: Set<string>
): string[] {
  const sorted = [...residual].sort();
  for (const start of sorted) {
    const path: string[] = [start];
    const inPath = new Set<string>([start]);
    const result = dfsCycle(start, start, idToTask, residual, path, inPath);
    if (result) return result;
  }
  return [];
}

function dfsCycle(
  start: string,
  node: string,
  idToTask: Map<string, Task>,
  residual: Set<string>,
  path: string[],
  inPath: Set<string>
): string[] | null {
  const t = idToTask.get(node)!;
  const deps = t.dependsOn.filter((d) => residual.has(d)).sort();
  for (const next of deps) {
    if (next === start) {
      return [...path, start];
    }
    if (!inPath.has(next)) {
      path.push(next);
      inPath.add(next);
      const r = dfsCycle(start, next, idToTask, residual, path, inPath);
      if (r) return r;
      path.pop();
      inPath.delete(next);
    }
  }
  return null;
}

interface PlanResult {
  order: string[];
  layers: string[][];
  earliest: Record<string, { start: number; finish: number }>;
  totalDuration: number;
  criticalPath: string[];
}

function plan(tasks: Task[]): PlanResult {
  const idToTask = new Map<string, Task>();
  for (const t of tasks) idToTask.set(t.id, t);
  const ids = tasks.map((t) => t.id);
  const sortedIds = [...ids].sort();

  const indeg = new Map<string, number>();
  const dependents = new Map<string, string[]>();
  for (const id of sortedIds) {
    indeg.set(id, 0);
    dependents.set(id, []);
  }
  for (const t of tasks) {
    indeg.set(t.id, t.dependsOn.length);
    for (const d of t.dependsOn) {
      dependents.get(d)!.push(t.id);
    }
  }

  const order: string[] = [];
  const ready: string[] = [];
  for (const id of sortedIds) if (indeg.get(id) === 0) ready.push(id);
  const indegWork = new Map(indeg);
  while (ready.length > 0) {
    ready.sort();
    const cur = ready.shift()!;
    order.push(cur);
    for (const dep of dependents.get(cur)!) {
      indegWork.set(dep, indegWork.get(dep)! - 1);
      if (indegWork.get(dep) === 0) ready.push(dep);
    }
  }

  if (order.length !== tasks.length) {
    const residual = new Set<string>();
    for (const id of sortedIds) if (indegWork.get(id)! > 0) residual.add(id);
    const cycle = findCycle(idToTask, residual);
    fail(`Cycle detected: ${cycle.join(" -> ")}`);
  }

  const layerIndex = new Map<string, number>();
  for (const id of order) {
    const t = idToTask.get(id)!;
    let li = 0;
    for (const d of t.dependsOn) {
      li = Math.max(li, layerIndex.get(d)! + 1);
    }
    layerIndex.set(id, li);
  }
  const layers: string[][] = [];
  for (const id of order) {
    const li = layerIndex.get(id)!;
    while (layers.length <= li) layers.push([]);
    layers[li].push(id);
  }
  for (const layer of layers) layer.sort();

  const start = new Map<string, number>();
  const finish = new Map<string, number>();
  for (const id of order) {
    const t = idToTask.get(id)!;
    let s = 0;
    for (const d of t.dependsOn) {
      s = Math.max(s, finish.get(d)!);
    }
    start.set(id, s);
    finish.set(id, s + t.duration);
  }

  const totalDuration =
    tasks.length === 0 ? 0 : Math.max(...[...finish.values()]);

  const path = new Map<string, string[]>();
  for (const id of order) {
    const t = idToTask.get(id)!;
    const s = start.get(id)!;
    const candidates: string[][] = [];
    if (s === 0) candidates.push([id]);
    for (const d of t.dependsOn) {
      if (finish.get(d) === s) {
        candidates.push([...path.get(d)!, id]);
      }
    }
    candidates.sort(cmpSeq);
    path.set(id, candidates[0]);
  }

  let criticalPath: string[] = [];
  if (tasks.length > 0) {
    const finishers = ids.filter((id) => finish.get(id) === totalDuration);
    const candidates = finishers.map((id) => path.get(id)!);
    candidates.sort(cmpSeq);
    criticalPath = candidates[0];
  }

  const earliest: Record<string, { start: number; finish: number }> = {};
  for (const id of sortedIds) {
    earliest[id] = { start: start.get(id)!, finish: finish.get(id)! };
  }

  return { order, layers, earliest, totalDuration, criticalPath };
}

function main(): void {
  const argv = process.argv.slice(2);
  if (argv.length === 0) {
    fail("Usage: bun run src/cli.ts plan INPUT.json");
  }
  const command = argv[0];
  if (command !== "plan") {
    fail(`Unknown command: '${command}'. Available commands: plan`);
  }
  const positional = argv.slice(1);
  for (const a of positional) {
    if (a.startsWith("-")) {
      fail(`Unknown flag: '${a}'`);
    }
  }
  if (positional.length !== 1) {
    fail("Expected exactly one input file argument.");
  }
  const inputPath = positional[0];
  let content: string;
  try {
    content = readFileSync(inputPath, "utf-8");
  } catch {
    fail(`Cannot read input file: ${inputPath}`);
  }
  let raw: unknown;
  try {
    raw = JSON.parse(content);
  } catch (e) {
    fail(`Invalid JSON in ${inputPath}: ${(e as Error).message}`);
  }
  const tasks = parseTasks(raw);
  const result = plan(tasks);
  process.stdout.write(JSON.stringify(result) + "\n");
}

main();

import { test, expect } from "bun:test";
import { spawnSync } from "bun";
import { writeFileSync, mkdtempSync } from "fs";
import { tmpdir } from "os";
import { join } from "path";

const CLI = join(import.meta.dir, "..", "src", "cli.ts");

function run(input: unknown) {
  const dir = mkdtempSync(join(tmpdir(), "dp-"));
  const file = join(dir, "input.json");
  writeFileSync(file, JSON.stringify(input));
  const res = spawnSync(["bun", "run", CLI, "plan", file], {
    stdout: "pipe",
    stderr: "pipe",
  });
  return {
    status: res.status,
    stdout: res.stdout?.toString() ?? "",
    stderr: res.stderr?.toString() ?? "",
  };
}

function runRaw(content: string) {
  const dir = mkdtempSync(join(tmpdir(), "dp-"));
  const file = join(dir, "input.json");
  writeFileSync(file, content);
  const res = spawnSync(["bun", "run", CLI, "plan", file], {
    stdout: "pipe",
    stderr: "pipe",
  });
  return {
    status: res.status,
    stdout: res.stdout?.toString() ?? "",
    stderr: res.stderr?.toString() ?? "",
  };
}

test("basic two-task chain", () => {
  const r = run({
    tasks: [
      { id: "lint", duration: 1 },
      { id: "build", duration: 3, dependsOn: ["lint"] },
    ],
  });
  expect(r.status).toBe(0);
  const out = JSON.parse(r.stdout);
  expect(out.order).toEqual(["lint", "build"]);
  expect(out.layers).toEqual([["lint"], ["build"]]);
  expect(out.earliest).toEqual({
    lint: { start: 0, finish: 1 },
    build: { start: 1, finish: 4 },
  });
  expect(out.totalDuration).toBe(4);
  expect(out.criticalPath).toEqual(["lint", "build"]);
});

test("empty tasks", () => {
  const r = run({ tasks: [] });
  expect(r.status).toBe(0);
  const out = JSON.parse(r.stdout);
  expect(out.order).toEqual([]);
  expect(out.layers).toEqual([]);
  expect(out.earliest).toEqual({});
  expect(out.totalDuration).toBe(0);
  expect(out.criticalPath).toEqual([]);
});

test("dependsOn defaults to empty", () => {
  const r = run({
    tasks: [
      { id: "a", duration: 2 },
      { id: "b", duration: 2 },
    ],
  });
  expect(r.status).toBe(0);
  const out = JSON.parse(r.stdout);
  expect(out.order).toEqual(["a", "b"]);
  expect(out.layers).toEqual([["a", "b"]]);
  expect(out.totalDuration).toBe(2);
});

test("lexicographic tie-breaking in order", () => {
  const r = run({
    tasks: [
      { id: "z", duration: 1 },
      { id: "a", duration: 1 },
      { id: "m", duration: 1 },
    ],
  });
  expect(r.status).toBe(0);
  const out = JSON.parse(r.stdout);
  expect(out.order).toEqual(["a", "m", "z"]);
  expect(out.layers).toEqual([["a", "m", "z"]]);
});

test("layers place task in earliest layer after deps", () => {
  const r = run({
    tasks: [
      { id: "a", duration: 1 },
      { id: "b", duration: 1 },
      { id: "c", duration: 1, dependsOn: ["a"] },
      { id: "d", duration: 1, dependsOn: ["a", "b"] },
    ],
  });
  expect(r.status).toBe(0);
  const out = JSON.parse(r.stdout);
  expect(out.layers).toEqual([["a", "b"], ["c", "d"]]);
});

test("earliest with unlimited parallelism", () => {
  const r = run({
    tasks: [
      { id: "a", duration: 5 },
      { id: "b", duration: 2 },
      { id: "c", duration: 3, dependsOn: ["a", "b"] },
    ],
  });
  expect(r.status).toBe(0);
  const out = JSON.parse(r.stdout);
  expect(out.earliest.a).toEqual({ start: 0, finish: 5 });
  expect(out.earliest.b).toEqual({ start: 0, finish: 2 });
  expect(out.earliest.c).toEqual({ start: 5, finish: 8 });
  expect(out.totalDuration).toBe(8);
  expect(out.criticalPath).toEqual(["a", "c"]);
});

test("critical path lexicographic tie-break", () => {
  // Two parallel chains of equal total duration: a->c (1+2=3) and b->d (1+2=3)
  // criticalPath should be the lexicographically smaller full sequence.
  const r = run({
    tasks: [
      { id: "a", duration: 1 },
      { id: "b", duration: 1 },
      { id: "c", duration: 2, dependsOn: ["a"] },
      { id: "d", duration: 2, dependsOn: ["b"] },
    ],
  });
  expect(r.status).toBe(0);
  const out = JSON.parse(r.stdout);
  expect(out.totalDuration).toBe(3);
  expect(out.criticalPath).toEqual(["a", "c"]);
});

test("zero-duration tasks work", () => {
  const r = run({
    tasks: [
      { id: "a", duration: 0 },
      { id: "b", duration: 0, dependsOn: ["a"] },
      { id: "c", duration: 2, dependsOn: ["b"] },
    ],
  });
  expect(r.status).toBe(0);
  const out = JSON.parse(r.stdout);
  expect(out.earliest.a).toEqual({ start: 0, finish: 0 });
  expect(out.earliest.b).toEqual({ start: 0, finish: 0 });
  expect(out.earliest.c).toEqual({ start: 0, finish: 2 });
  expect(out.totalDuration).toBe(2);
  expect(out.criticalPath).toEqual(["a", "b", "c"]);
});

test("disconnected components", () => {
  const r = run({
    tasks: [
      { id: "x", duration: 2, dependsOn: ["y"] },
      { id: "y", duration: 1 },
      { id: "p", duration: 4, dependsOn: ["q"] },
      { id: "q", duration: 1 },
    ],
  });
  expect(r.status).toBe(0);
  const out = JSON.parse(r.stdout);
  expect(out.totalDuration).toBe(5);
  expect(out.criticalPath).toEqual(["p", "q"]);
});

test("cycle is reported with repeated node", () => {
  const r = run({
    tasks: [
      { id: "a", duration: 1, dependsOn: ["b"] },
      { id: "b", duration: 1, dependsOn: ["a"] },
    ],
  });
  expect(r.status).not.toBe(0);
  expect(r.stderr).toContain("Cycle detected:");
  expect(r.stderr).toContain("a -> b -> a");
});

test("self-dependency is rejected", () => {
  const r = run({
    tasks: [{ id: "a", duration: 1, dependsOn: ["a"] }],
  });
  expect(r.status).not.toBe(0);
  expect(r.stderr).toContain("cannot depend on itself");
});

test("unknown dependency is rejected", () => {
  const r = run({
    tasks: [{ id: "a", duration: 1, dependsOn: ["ghost"] }],
  });
  expect(r.status).not.toBe(0);
  expect(r.stderr).toContain("unknown dependency");
});

test("duplicate id is rejected", () => {
  const r = run({
    tasks: [
      { id: "a", duration: 1 },
      { id: "a", duration: 2 },
    ],
  });
  expect(r.status).not.toBe(0);
  expect(r.stderr).toContain("duplicate id");
});

test("negative duration is rejected", () => {
  const r = run({
    tasks: [{ id: "a", duration: -1 }],
  });
  expect(r.status).not.toBe(0);
  expect(r.stderr).toContain("duration");
});

test("non-number duration is rejected", () => {
  const r = run({
    tasks: [{ id: "a", duration: "fast" }],
  });
  expect(r.status).not.toBe(0);
  expect(r.stderr).toContain("duration");
});

test("invalid JSON fails", () => {
  const r = runRaw("{ not json");
  expect(r.status).not.toBe(0);
  expect(r.stderr).toContain("Invalid JSON");
});

test("tasks not array fails", () => {
  const r = run({ tasks: "nope" });
  expect(r.status).not.toBe(0);
  expect(r.stderr).toContain("must be an array");
});

test("unknown command fails", () => {
  const dir = mkdtempSync(join(tmpdir(), "dp-"));
  const file = join(dir, "input.json");
  writeFileSync(file, JSON.stringify({ tasks: [] }));
  const res = spawnSync(["bun", "run", CLI, "bogus", file], {
    stdout: "pipe",
    stderr: "pipe",
  });
  expect(res.status).not.toBe(0);
  expect((res.stderr?.toString() ?? "")).toContain("Unknown command");
});

test("unknown flag fails", () => {
  const dir = mkdtempSync(join(tmpdir(), "dp-"));
  const file = join(dir, "input.json");
  writeFileSync(file, JSON.stringify({ tasks: [] }));
  const res = spawnSync(["bun", "run", CLI, "plan", "--fast", file], {
    stdout: "pipe",
    stderr: "pipe",
  });
  expect(res.status).not.toBe(0);
  expect((res.stderr?.toString() ?? "")).toContain("Unknown flag");
});

test("diamond dependency", () => {
  const r = run({
    tasks: [
      { id: "a", duration: 1 },
      { id: "b", duration: 2, dependsOn: ["a"] },
      { id: "c", duration: 3, dependsOn: ["a"] },
      { id: "d", duration: 1, dependsOn: ["b", "c"] },
    ],
  });
  expect(r.status).toBe(0);
  const out = JSON.parse(r.stdout);
  expect(out.order).toEqual(["a", "b", "c", "d"]);
  expect(out.layers).toEqual([["a"], ["b", "c"], ["d"]]);
  expect(out.earliest.d).toEqual({ start: 4, finish: 5 });
  expect(out.totalDuration).toBe(5);
  expect(out.criticalPath).toEqual(["a", "c", "d"]);
});

